 */

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelFillDiagonalV2 {
public:
    __aicore__ inline KernelFillDiagonalV2() {}

    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int64_t formerNum, int64_t formerLength,
        int64_t tailNum, int64_t tailLength, int64_t tileLength,
        int64_t M, int64_t N, int64_t diagLength, int64_t batchStride,
        int64_t wrap, int64_t fillValueBits)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            this->coreOffset = formerLength * blockIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + this->coreOffset, formerLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + this->coreOffset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            this->coreOffset = formerLength * formerNum + tailLength * tailIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + this->coreOffset, tailLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + this->coreOffset, tailLength);
        }

        this->tileLength = tileLength;
        this->M = M;
        this->N = N;
        this->diagLength = diagLength;
        this->batchStride = batchStride;
        this->wrap = wrap;
        this->fillValueBits = fillValueBits;

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
    }

    __aicore__ inline void Process()
    {
        if (this->blockLength <= 0) {
            return;
        }
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;

        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        if (alignNum <= 0) { alignNum = 1; }

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            int64_t curLen = this->tileLength;
            CopyIn(i, curLen);
            Compute(i, curLen);
            CopyOut(i, curLen);
        }
        if (tileNum > 0) {
            int64_t curLen = this->blockLength - (tileNum - 1) * this->tileLength;
            int64_t alignedLen = ((curLen + alignNum - 1) / alignNum) * alignNum;
            CopyIn(tileNum - 1, alignedLen);
            Compute(tileNum - 1, curLen);
            CopyOut(tileNum - 1, curLen);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curLen)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curLen * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParams, padParams);
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curLen)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();

        // Copy data unchanged (UB to UB)
        AscendC::DataCopy(yLocal, xLocal, curLen);

        // Modify diagonal positions within this tile
        int64_t tileStart = this->coreOffset + progress * this->tileLength;
        int64_t tileEnd = tileStart + curLen;

        // Fill value: reinterpret the bytes as type T
        T fillT;
        const char *src = reinterpret_cast<const char *>(&(this->fillValueBits));
        char *dst = reinterpret_cast<char *>(&fillT);
        for (int32_t b = 0; b < static_cast<int32_t>(sizeof(T)); ++b) {
            dst[b] = src[b];
        }

        // Find batches overlapping with this tile
        int64_t firstBatch = tileStart / this->batchStride;
        int64_t lastBatch = (tileEnd - 1) / this->batchStride;

        for (int64_t bi = firstBatch; bi <= lastBatch; ++bi) {
            int64_t batchBase = bi * this->batchStride;

            for (int64_t di = 0; di < this->diagLength; ++di) {
                int64_t diagPos;
                if (this->wrap != 0) {
                    // wrap=True: position = batchBase + di * N + (di % N)
                    diagPos = batchBase + di * this->N + (di % this->N);
                } else {
                    // wrap=False: position = batchBase + di * (N + 1)
                    diagPos = batchBase + di * (this->N + 1);
                }

                if (diagPos < tileStart) {
                    continue;
                }
                if (diagPos >= tileEnd) {
                    break;
                }

                int64_t localIdx = diagPos - tileStart;
                yLocal.SetValue(localIdx, fillT);
            }
        }

        outQueueY.EnQue<T>(yLocal);
        inQueueX.FreeTensor(xLocal);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curLen)
    {
        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curLen * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(yGm[progress * this->tileLength], yLocal, copyParams);
        outQueueY.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<T> yGm;
    int64_t blockLength;
    int64_t coreOffset;
    int64_t tileLength;
    int64_t M;
    int64_t N;
    int64_t diagLength;
    int64_t batchStride;
    int64_t wrap;
    int64_t fillValueBits;
};

extern "C" __global__ __aicore__ void fill_diagonal_v2(
    GM_ADDR x, GM_ADDR y,
    int64_t formerNum, int64_t formerLength,
    int64_t tailNum, int64_t tailLength, int64_t tileLength,
    int64_t M, int64_t N, int64_t diagLength, int64_t batchStride,
    int64_t wrap, int64_t dtypeSize, int64_t fillValueBits)
{
    if (dtypeSize == 1) {
        KernelFillDiagonalV2<uint8_t> op;
        op.Init(x, y, formerNum, formerLength, tailNum, tailLength, tileLength,
                M, N, diagLength, batchStride, wrap, fillValueBits);
        op.Process();
    } else if (dtypeSize == 2) {
        KernelFillDiagonalV2<half> op;
        op.Init(x, y, formerNum, formerLength, tailNum, tailLength, tileLength,
                M, N, diagLength, batchStride, wrap, fillValueBits);
        op.Process();
    } else if (dtypeSize == 4) {
        KernelFillDiagonalV2<float> op;
        op.Init(x, y, formerNum, formerLength, tailNum, tailLength, tileLength,
                M, N, diagLength, batchStride, wrap, fillValueBits);
        op.Process();
    } else {
        // dtypeSize == 8 (float64 / int64)
        KernelFillDiagonalV2<int64_t> op;
        op.Init(x, y, formerNum, formerLength, tailNum, tailLength, tileLength,
                M, N, diagLength, batchStride, wrap, fillValueBits);
        op.Process();
    }
}
