#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_fill_diagonal_v2.h"

#include <cstring>

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
constexpr int64_t UB_ALIGN_BYTES = 32;

static int64_t extractFillValueBits(const at::Tensor &fillTensor, int64_t dtypeSize)
{
    auto fillCpu = fillTensor.cpu().contiguous();
    int64_t result = 0;
    if (dtypeSize == 1) {
        uint8_t v = *static_cast<const uint8_t *>(fillCpu.data_ptr());
        std::memcpy(&result, &v, sizeof(uint8_t));
    } else if (dtypeSize == 2) {
        uint16_t v = *static_cast<const uint16_t *>(fillCpu.data_ptr());
        std::memcpy(&result, &v, sizeof(uint16_t));
    } else if (dtypeSize == 4) {
        uint32_t v = *static_cast<const uint32_t *>(fillCpu.data_ptr());
        std::memcpy(&result, &v, sizeof(uint32_t));
    } else {  // dtypeSize == 8
        std::memcpy(&result, fillCpu.data_ptr(), sizeof(int64_t));
    }
    return result;
}

at::Tensor fill_diagonal_v2(
    const at::Tensor &x,
    const at::Tensor &fillTensor,
    bool wrap)
{
    // ---- Shorthand for shape analysis ----
    auto shape = x.sizes();
    int64_t dims = static_cast<int64_t>(shape.size());
    int64_t M = shape[dims - 2];
    int64_t N = shape[dims - 1];
    int64_t batchStride = M * N;

    int64_t diagLength;
    if (wrap) {
        diagLength = M;
    } else {
        diagLength = (M < N) ? M : N;
    }

    int64_t totalLength = x.numel();
    int64_t dtypeSize = x.element_size();

    // Create output
    at::Tensor output = at::empty_like(x);

    if (totalLength == 0) {
        return output;
    }

    // ---- Extract fill value bits ----
    int64_t fillValueBits = extractFillValueBits(fillTensor, dtypeSize);

    // ---- Get hardware parameters ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block-level tiling (Cache Line alignment) ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t clsElements = CACHE_LINE_BYTE_LENGTH / dtypeSize;
    if (clsElements <= 0) { clsElements = 1; }
    int64_t totalLengthCoreAlign = ((totalLengthCore + clsElements - 1) / clsElements) * clsElements;

