    (void)padding1;

    // Compute workspace size for tiling data
    constexpr int64_t TILING_DATA_SIZE = 256;  // conservative size, > our 12*8=96
    auto tilingWorkspace = at::empty(
        {TILING_DATA_SIZE},
        at::TensorOptions().dtype(at::kByte).device(x.device()));

    // Write tiling parameters into workspace for kernel
    auto tilingCpu = at::empty(
        {TILING_DATA_SIZE},
        at::TensorOptions().dtype(at::kByte).device(at::kCPU));
    int64_t *tilingPtr = static_cast<int64_t *>(tilingCpu.data_ptr());
