    tilingPtr[1] = M;
    tilingPtr[2] = N;
    tilingPtr[3] = diagLength;
    tilingPtr[4] = batchStride;
    tilingPtr[5] = wrapInt;
    tilingPtr[6] = formerNum;
    tilingPtr[7] = formerLength;
    tilingPtr[8] = tailNum;
    tilingPtr[9] = tailLength;
    tilingPtr[10] = tileLength;
    tilingPtr[11] = dtypeSize;
    tilingPtr[12] = fillValueBits;

    // Copy tiling data to device
    at::Tensor tilingDevice = TorchNpuHelper::CopyTensorHostToDevice(tilingCpu);

    EXEC_KERNEL_CMD(fill_diagonal_v2, blockDim,
                    x, output,
                    formerNum, formerLength, tailNum, tailLength, tileLength,
                    M, N, diagLength, batchStride,
                    wrapInt, dtypeSize, fillValueBits);

