22	static int64_t extractFillValueBits(const at::Tensor &fillTensor, int64_t dtypeSize)
23	{
24	    auto fillCpu = fillTensor.cpu().contiguous();
25	    int64_t result = 0;
26	    if (dtypeSize == 1) {
27	        uint8_t v = *static_cast<const uint8_t *>(fillCpu.data_ptr());
28	        std::memcpy(&result, &v, sizeof(uint8_t));
29	    } else if (dtypeSize == 2) {
30	        uint16_t v = *static_cast<const uint16_t *>(fillCpu.data_ptr());
31	        std::memcpy(&result, &v, sizeof(uint16_t));
32	    } else if (dtypeSize == 4) {
33	        uint32_t v = *static_cast<const uint32_t *>(fillCpu.data_ptr());
34	        std::memcpy(&result, &v, sizeof(uint32_t));
35	    } else {  // dtypeSize == 8
36	        std::memcpy(&result, fillCpu.data_ptr(), sizeof(int64_t));
37	    }
38	    return result;
39	}
