61	    {
62	        if (this->blockLength <= 0 || this->tileLength <= 0) {
63	            return;
64	        }
65	
66	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
67	
68	        for (int64_t i = 0; i < tileNum; ++i) {
69	            int64_t curLen = this->tileLength;
70	            if (i == tileNum - 1) {
71	                curLen = this->blockLength - i * this->tileLength;
72	            }
73	            CopyIn(i, curLen);
74	            Compute(i, curLen);
75	            CopyOut(i, curLen);
76	        }
77	    }
