namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
constexpr int64_t UB_ALIGN_BYTES = 32;

static int64_t extractFillValueBits(const at::Tensor &fillTensor, int64_t dtypeSize)
{
    auto fillCpu = fillTensor.cpu().contiguous();
    int64_t result = 0;
    if (dtypeSize == 1) {
        uint8_t v = *static_cast<const uint8_t *>(fillCpu.data_ptr());
        std::memcpy(&result, &v, sizeof(uint8_t));
    } else if (dtypeSize == 2) {
        uint16_t v = *static_cast<const uint16_t *>(fillCpu.data_ptr());
        std::memcpy(&result, &v, sizeof(uint16_t));
    } else if (dtypeSize == 4) {
        uint32_t v = *static_cast<const uint32_t *>(fillCpu.data_ptr());
        std::memcpy(&result, &v, sizeof(uint32_t));
    } else {  // dtypeSize == 8
        std::memcpy(&result, fillCpu.data_ptr(), sizeof(int64_t));
    }
    return result;
}

at::Tensor fill_diagonal_v2(
    const at::Tensor &x,
    const at::Tensor &fillTensor,
    bool wrap)
{
    auto shape = x.sizes();
    int64_t dims = static_cast<int64_t>(shape.size());
    int64_t M = shape[dims - 2];
    int64_t N = shape[dims - 1];
    int64_t totalLength = x.numel();
    int64_t dtypeSize = x.element_size();

    // Detect cubic tensors (all dims equal, dims > 2)
    int64_t isCubic = 0;
    int64_t diagStride = 0;
    int64_t diagLength;
    int64_t batchStride = M * N;

    if (dims > 2) {
        bool allEqual = true;
        int64_t firstDim = shape[0];
        for (int64_t d = 1; d < dims; ++d) {
            if (shape[d] != firstDim) {
                allEqual = false;
                break;
            }
        }
        if (allEqual) {
            // Cubic tensor: volume diagonal at stride sum of partial dim products
            isCubic = 1;
            diagStride = 0;
            int64_t prod = 1;
            for (int64_t d = dims - 1; d >= 0; --d) {
                diagStride += prod;
                prod *= firstDim;
            }
            diagLength = firstDim;
            batchStride = 0; // not used for cubic
        }
    }

    if (!isCubic) {
        if (wrap) {
            // Non-cubic wrap=True: N+1 stride until end of M*N block
            diagLength = (M * N + (N + 1) - 1) / (N + 1);
        } else {
            diagLength = (M < N) ? M : N;
        }
    }

    // Create output as a clone (preserves all data, kernel only modifies diagonal)
    at::Tensor output = x.clone();

    if (totalLength == 0) {
        return output;
    }

    // ---- Extract fill value bits ----
    int64_t fillValueBits = extractFillValueBits(fillTensor, dtypeSize);

    // ---- Get hardware parameters ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block-level tiling (Cache Line alignment) ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t clsElements = CACHE_LINE_BYTE_LENGTH / dtypeSize;
    if (clsElements <= 0) { clsElements = 1; }
    int64_t totalLengthCoreAlign = ((totalLengthCore + clsElements - 1) / clsElements) * clsElements;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    if (usedCoreNum <= 0) { usedCoreNum = 1; }
    int64_t formerNum = usedCoreNum - 1;
    if (formerNum < 0) { formerNum = 0; }
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailNum = usedCoreNum - formerNum;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // ---- UB-level tiling ----
    int64_t bufferCoefficient;
    switch (dtypeSize) {
        case 1:  bufferCoefficient = 8;  break;
        case 2:  bufferCoefficient = 16; break;
        case 4:  bufferCoefficient = 24; break;
        default: bufferCoefficient = 48; break;
    }

    if (bufferCoefficient <= 0) { bufferCoefficient = 1; }
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    int64_t alignElements = UB_ALIGN_BYTES / dtypeSize;
    if (alignElements <= 0) { alignElements = 1; }
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength <= 0) { tileLength = alignElements; }

    // Prepare left-value parameters for EXEC_KERNEL_CMD
    int64_t wrapInt = wrap ? 1 : 0;
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(fill_diagonal_v2, blockDim,
                    output, output,
                    formerNum, formerLength, tailNum, tailLength, tileLength,
                    M, N, diagLength, batchStride,
                    isCubic, diagStride, wrapInt, dtypeSize, fillValueBits);

    return output;
}

}  // namespace ascend_kernel
