13	constexpr int32_t BUFFER_NUM = 2;
14	
15	template <typename T>
16	class KernelFillDiagonalV2 {
17	public:
18	    __aicore__ inline KernelFillDiagonalV2() {}
19	
20	    __aicore__ inline void Init(
21	        GM_ADDR x, GM_ADDR y,
22	        int64_t formerNum, int64_t formerLength,
23	        int64_t tailNum, int64_t tailLength, int64_t tileLength,
24	        int64_t M, int64_t N, int64_t diagLength, int64_t batchStride,
25	        int64_t wrap, int64_t fillValueBits)
26	    {
27	        int64_t blockIdx = AscendC::GetBlockIdx();
28	        int64_t usedCoreNum = formerNum + tailNum;
29	
30	        if (blockIdx < usedCoreNum) {
31	            if (blockIdx < formerNum) {
32	                this->blockLength = formerLength;
33	                this->coreOffset = formerLength * blockIdx;
34	            } else {
35	                this->blockLength = tailLength;
36	                int64_t tailIdx = blockIdx - formerNum;
37	                this->coreOffset = formerLength * formerNum + tailLength * tailIdx;
38	            }
39	            xGm.SetGlobalBuffer((__gm__ T *)x + this->coreOffset, this->blockLength);
40	            yGm.SetGlobalBuffer((__gm__ T *)y + this->coreOffset, this->blockLength);
41	        } else {
42	            this->blockLength = 0;
43	            this->coreOffset = 0;
44	        }
45	
46	        this->tileLength = tileLength;
47	        this->M = M;
48	        this->N = N;
49	        this->diagLength = diagLength;
50	        this->batchStride = batchStride;
51	        this->wrap = wrap;
52	        this->fillValueBits = fillValueBits;
53	
54	        // Always init buffers (even idle cores need a valid TPipe)
55	        int64_t bufSize = (this->blockLength > 0) ? tileLength * sizeof(T) : (32);
56	        bufSize = (bufSize > 0) ? bufSize : 32;
57	        pipe.InitBuffer(inQueueX, BUFFER_NUM, bufSize);
58	        pipe.InitBuffer(outQueueY, BUFFER_NUM, bufSize);
59	    }
60	
61	    __aicore__ inline void Process()
62	    {
63	        if (this->blockLength <= 0 || this->tileLength <= 0) {
64	            return;
65	        }
66	
67	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
68	
69	        for (int64_t i = 0; i < tileNum; ++i) {
70	            int64_t curLen = this->tileLength;
71	            if (i == tileNum - 1) {
72	                curLen = this->blockLength - i * this->tileLength;
73	            }
74	            CopyIn(i, curLen);
75	            Compute(i, curLen);
76	            CopyOut(i, curLen);
77	        }
78	    }
79	
80	private:
81	    __aicore__ inline void CopyIn(int64_t progress, int64_t curLen)
82	    {
83	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
84	        uint32_t blockLenBytes = static_cast<uint32_t>(curLen * sizeof(T));
85	        AscendC::DataCopyExtParams copyParams{1, blockLenBytes, 0, 0, 0};
86	        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
87	        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParams, padParams);
88	        inQueueX.EnQue(xLocal);
89	    }
90	
91	    __aicore__ inline void Compute(int64_t progress, int64_t curLen)
92	    {
93	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
94	        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
95	
96	        // Copy input to output buffer (UB to UB)
97	        AscendC::DataCopy(yLocal, xLocal, curLen);
98	
99	        int64_t tileStart = this->coreOffset + progress * this->tileLength;
100	        int64_t tileEnd = tileStart + curLen;
101	
102	        // Build fill value by reinterpreting raw bits
103	        T fillT;
104	        const char *src = reinterpret_cast<const char *>(&(this->fillValueBits));
105	        char *dst = reinterpret_cast<char *>(&fillT);
106	        for (int32_t b = 0; b < static_cast<int32_t>(sizeof(T)); ++b) {
107	            dst[b] = src[b];
108	        }
109	
110	        // Iterate over all batches that overlap with [tileStart, tileEnd)
111	        int64_t firstBatch = tileStart / this->batchStride;
112	        int64_t lastBatch = (tileEnd - 1) / this->batchStride;
113	
114	        for (int64_t bi = firstBatch; bi <= lastBatch; ++bi) {
115	            int64_t batchBase = bi * this->batchStride;
116	
117	            for (int64_t di = 0; di < this->diagLength; ++di) {
118	                // Both wrap=True and wrap=False use the same flat index formula:
119	                // positions at stride (N+1) in the flat view
120	                int64_t diagPos = batchBase + di * (this->N + 1);
121	
122	                if (diagPos < tileStart) {
123	                    continue;
124	                }
125	                if (diagPos >= tileEnd) {
126	                    break;
127	                }
128	
129	                int64_t localIdx = diagPos - tileStart;
130	                yLocal.SetValue(localIdx, fillT);
131	            }
132	        }
133	
134	        outQueueY.EnQue<T>(yLocal);
135	        inQueueX.FreeTensor(xLocal);
136	    }
137	
138	    __aicore__ inline void CopyOut(int64_t progress, int64_t curLen)
139	    {
140	        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
141	        uint32_t blockLenBytes = static_cast<uint32_t>(curLen * sizeof(T));
142	        AscendC::DataCopyExtParams copyParams{1, blockLenBytes, 0, 0, 0};
143	        AscendC::DataCopyPad(yGm[progress * this->tileLength], yLocal, copyParams);
144	        outQueueY.FreeTensor(yLocal);
145	    }
